:root{
 --vscode-font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif;
 --vscode-editor-font-family:Menlo,Monaco,"Courier New",monospace;
 --vscode-foreground:#cccccc; --vscode-descriptionForeground:#a0a0a0; --vscode-disabledForeground:#8b8b8b;
 --vscode-editor-background:#1e1e1e; --vscode-editor-foreground:#d4d4d4;
 --vscode-sideBar-background:#252526; --vscode-activityBar-background:#333333; --vscode-titleBar-activeBackground:#3c3c3c;
 --vscode-sideBarSectionHeader-border:#cccccc33; --vscode-panel-border:#3c3c3c;
 --vscode-list-activeSelectionBackground:#04395e; --vscode-list-hoverBackground:#2a2d2e; --vscode-list-inactiveSelectionBackground:#37373d;
 --vscode-button-background:#0e639c; --vscode-button-foreground:#ffffff; --vscode-button-secondaryBackground:#3a3d41; --vscode-button-secondaryForeground:#cccccc;
 --vscode-input-background:#3c3c3c; --vscode-input-foreground:#cccccc; --vscode-input-placeholderForeground:#a6a6a6;
 --vscode-focusBorder:#007fd4; --vscode-badge-background:#4d4d4d; --vscode-badge-foreground:#ffffff; --vscode-activityBarBadge-background:#007acc;
 --vscode-textLink-foreground:#3794ff; --vscode-errorForeground:#f48771; --vscode-list-warningForeground:#cca700;
 --vscode-charts-green:#89d185; --vscode-charts-blue:#3794ff; --vscode-charts-orange:#d18616;
 --vscode-tab-activeBackground:#1e1e1e; --vscode-tab-inactiveBackground:#2d2d2d; --vscode-tab-border:#252526;
 --vscode-statusBar-background:#007acc; --vscode-statusBar-foreground:#ffffff;
 --vscode-editorWidget-background:#252526; --vscode-editorWidget-border:#454545; --vscode-quickInput-background:#252526;
 --vscode-textBlockQuote-background:#2b2b2b; --vscode-inputValidation-infoBorder:#007acc;
}
.wb{font-family:var(--vscode-font-family);font-size:13px;color:var(--vscode-foreground);background:var(--vscode-editor-background);
 display:grid;grid-template-rows:30px 1fr 22px;height:820px;border:1px solid #000;border-radius:6px;overflow:hidden;min-width:0}
.wb *{box-sizing:border-box}
.title{background:var(--vscode-titleBar-activeBackground);display:flex;align-items:center;justify-content:center;font-size:12px;color:#ccc;position:relative}
.title .dots{position:absolute;left:10px;display:flex;gap:7px}.title .dots i{width:11px;height:11px;border-radius:50%;background:#ff5f57}
.title .dots i:nth-child(2){background:#febc2e}.title .dots i:nth-child(3){background:#28c840}
.main{display:grid;grid-template-columns:48px var(--sbw,300px) 1fr;min-height:0}
.main.nosb{grid-template-columns:48px 1fr}
.act{background:var(--vscode-activityBar-background);display:flex;flex-direction:column;align-items:center;padding-top:6px;gap:4px}
.act span{width:48px;height:44px;display:flex;align-items:center;justify-content:center;font-size:20px;color:#858585;position:relative}
.act span.on{color:#fff;border-left:2px solid #fff}
.act b{position:absolute;right:7px;bottom:7px;background:var(--vscode-activityBarBadge-background);color:#fff;font-size:9px;border-radius:8px;padding:0 4px;line-height:14px;font-weight:600}
.sb{background:var(--vscode-sideBar-background);display:flex;flex-direction:column;min-height:0;overflow:hidden;border-right:1px solid var(--vscode-panel-border)}
.sbh{height:35px;display:flex;align-items:center;padding:0 12px 0 20px;font-size:11px;text-transform:uppercase;letter-spacing:.04em}
.sec{border-top:1px solid var(--vscode-sideBarSectionHeader-border);display:flex;flex-direction:column;min-height:0}
.sech{height:22px;display:flex;align-items:center;gap:4px;padding:0 8px 0 2px;font-size:11px;font-weight:700;text-transform:uppercase;cursor:pointer}
.sech .desc{font-weight:400;text-transform:none;color:var(--vscode-descriptionForeground);margin-left:6px;font-size:11px}
.sech .acts{margin-left:auto;display:flex;gap:6px;color:var(--vscode-foreground);font-weight:400}
.cnt{background:var(--vscode-badge-background);color:var(--vscode-badge-foreground);border-radius:9px;padding:0 6px;font-size:10px;font-weight:600;line-height:16px}
.tree{list-style:none;margin:0;padding:0}
.row{height:22px;display:flex;align-items:center;gap:6px;white-space:nowrap;overflow:hidden;cursor:pointer;padding-right:8px}
.row:hover{background:var(--vscode-list-hoverBackground)}
.row.sel{background:var(--vscode-list-activeSelectionBackground);outline:1px solid var(--vscode-focusBorder);outline-offset:-1px}
.row .tw{width:16px;text-align:center;color:#c5c5c5;flex:none}
.row .ic{width:16px;text-align:center;flex:none}
.row .lb{overflow:hidden;text-overflow:ellipsis;flex:none;max-width:60%}
.row .ds{color:var(--vscode-descriptionForeground);font-size:12px;overflow:hidden;text-overflow:ellipsis}
.row .bdg{margin-left:auto;font-weight:700;font-size:11px;flex:none}
.d1{padding-left:4px}.d2{padding-left:20px}.d3{padding-left:36px}
.ok{color:var(--vscode-charts-green)}.bl{color:var(--vscode-charts-blue)}.or{color:var(--vscode-charts-orange)}.er{color:var(--vscode-errorForeground)}.wn{color:var(--vscode-list-warningForeground)}.dim{color:var(--vscode-disabledForeground)}
.status{background:var(--vscode-statusBar-background);color:var(--vscode-statusBar-foreground);display:flex;align-items:center;gap:14px;padding:0 10px;font-size:12px}
.status .r{margin-left:auto}
.ed{display:flex;flex-direction:column;min-width:0;min-height:0}
.tabs{height:35px;background:var(--vscode-tab-inactiveBackground);display:flex;align-items:stretch}
.tab{padding:0 12px;display:flex;align-items:center;gap:6px;font-size:13px;color:#969696;border-right:1px solid var(--vscode-tab-border);white-space:nowrap}
.tab.on{background:var(--vscode-tab-activeBackground);color:#fff}
.tabs .etitle{margin-left:auto;display:flex;align-items:center;gap:2px;padding-right:8px}
.etitle button{background:none;border:0;color:var(--vscode-foreground);font-size:15px;width:26px;height:24px;border-radius:4px;cursor:pointer}
.etitle button:hover{background:var(--vscode-list-hoverBackground)}
.etitle button[disabled]{color:#5a5a5a}
.body{flex:1;overflow:auto;padding:20px 28px 28px;background:var(--vscode-editor-background);min-height:0}
button:focus-visible,a:focus-visible,.row:focus-visible{outline:1px solid var(--vscode-focusBorder);outline-offset:1px}
.btn{background:var(--vscode-button-background);color:var(--vscode-button-foreground);border:0;border-radius:2px;padding:4px 11px;font:inherit;cursor:pointer}
.btn.sec2{background:var(--vscode-button-secondaryBackground);color:var(--vscode-button-secondaryForeground)}
.inp{background:var(--vscode-input-background);color:var(--vscode-input-foreground);border:1px solid var(--vscode-input-background);border-radius:2px;padding:4px 6px;font:inherit;width:100%}
.inp.foc{border-color:var(--vscode-focusBorder)}
.tiles{display:flex;flex-wrap:wrap;gap:4px}
.tile{background:var(--vscode-button-secondaryBackground);color:var(--vscode-button-secondaryForeground);border:1px solid transparent;border-radius:3px;padding:3px 7px;font:inherit;font-size:12px;cursor:pointer;display:inline-flex;gap:6px;align-items:baseline}
.tile b{font-weight:700}
.tile[aria-pressed=true]{background:var(--vscode-list-activeSelectionBackground);border-color:var(--vscode-focusBorder);color:#fff}
.tile[aria-pressed=true]::before{content:"✓";}
.lbl{font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:var(--vscode-descriptionForeground);margin:10px 0 5px}
.card{background:var(--vscode-editorWidget-background);border:1px solid var(--vscode-editorWidget-border);border-radius:4px;padding:12px 14px}
a{color:var(--vscode-textLink-foreground);text-decoration:none}
a:hover{text-decoration:underline}
.chip{display:inline-block;border:1px solid var(--vscode-editorWidget-border);border-radius:12px;padding:2px 10px;font-size:12px;color:var(--vscode-foreground);background:none;font-family:inherit;cursor:pointer}
.chip[aria-pressed=true]{background:var(--vscode-button-background);border-color:var(--vscode-button-background);color:#fff}
.tbadge{display:inline-block;border-radius:3px;padding:1px 6px;font-size:11px;font-weight:600;background:#3a3d41}
.banner{border-left:3px solid var(--vscode-inputValidation-infoBorder);background:#063b4966;padding:8px 12px;font-size:12.5px;display:flex;gap:10px;align-items:center;margin-bottom:16px}
h1{font-size:20px;font-weight:600;margin:0 0 6px;color:#e7e7e7}
h2{font-size:14px;font-weight:600;margin:22px 0 8px;color:#e7e7e7;border-bottom:1px solid var(--vscode-panel-border);padding-bottom:4px}
h3{font-size:13px;font-weight:600;margin:16px 0 6px;color:#e7e7e7}
.meta{display:flex;flex-wrap:wrap;gap:6px 16px;font-size:12.5px;color:var(--vscode-descriptionForeground)}
.meta strong{color:var(--vscode-foreground);font-weight:500}
ul.plain{list-style:none;padding:0;margin:0}
.sorth{background:none;border:0;color:var(--vscode-foreground);font:inherit;font-weight:600;padding:6px 8px 6px 0;cursor:pointer}
td{padding:6px 8px 6px 0;border-bottom:1px solid #2d2d2d}code{font-family:var(--vscode-editor-font-family);font-size:12px;background:#2b2b2b;padding:0 4px;border-radius:3px}
summary:focus-visible{outline:1px solid var(--vscode-focusBorder)}
.va{background:none;border:0;color:var(--vscode-foreground);font:inherit;font-size:13px;width:20px;height:20px;border-radius:3px;cursor:pointer;padding:0}
.va:hover{background:var(--vscode-list-hoverBackground)}
.grp{background:none;border:0;color:var(--vscode-foreground);font:inherit;font-size:12.5px;font-weight:600;padding:3px 0;cursor:pointer;width:100%;text-align:left}
.trow{display:flex;align-items:center;gap:6px;height:24px;padding-left:14px;font-size:12.5px;white-space:nowrap}
.trow:hover{background:var(--vscode-list-hoverBackground)}
.trow .ic{width:16px;text-align:center;flex:none}
.trow .tt{background:none;border:0;color:var(--vscode-foreground);font:inherit;padding:0;cursor:pointer;flex:none;max-width:48%;overflow:hidden;text-overflow:ellipsis}
.trow .ds{color:var(--vscode-descriptionForeground);font-size:11.5px;overflow:hidden;text-overflow:ellipsis;flex:1;min-width:0}
.trow .bdg{font-weight:700;font-size:11px;flex:none}
.na{background:var(--vscode-button-background);color:#fff;border:0;border-radius:3px;font-size:10px;width:20px;height:18px;cursor:pointer;flex:none;margin-left:auto}
.row .na{margin-left:auto}
.row .ds{flex:1;min-width:0}
.kpil{color:inherit;text-decoration:none!important}.kpil .kpi{height:100%}.kpil:hover .kpi{border-color:var(--vscode-focusBorder)}
.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:16px 0 12px}
.kpi{display:flex;gap:10px;align-items:flex-start;background:var(--vscode-editorWidget-background);border:1px solid var(--vscode-editorWidget-border);border-radius:6px;padding:12px}
.kico{width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;color:#fff;flex:none}
.kval{font-size:24px;font-weight:600;color:#fff;line-height:28px}.klab{font-size:12px;color:var(--vscode-foreground)}.ksub{font-size:11px;color:var(--vscode-descriptionForeground);margin-top:2px}
.fbar{display:flex;align-items:center;gap:8px;font-size:12px;margin-bottom:10px;flex-wrap:wrap}.fbar .dim,.fbar label{white-space:nowrap}
.fchip{display:inline-flex;align-items:center;gap:4px;background:var(--vscode-list-activeSelectionBackground);border:1px solid var(--vscode-focusBorder);border-radius:10px;padding:1px 4px 1px 9px}
.fchip button{background:none;border:0;color:#fff;font-size:10px;cursor:pointer}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.chc{padding:12px 14px}.chh{display:flex;align-items:baseline}.chh h3{margin:0;font-size:13px}.tv{margin-left:auto;font-size:11.5px}
.chs{font-size:11.5px;color:var(--vscode-descriptionForeground);margin:2px 0 10px}.chf{font-size:11px;color:var(--vscode-descriptionForeground);margin-top:6px}
.hb{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:3px}
.hbr{width:100%;display:grid;grid-template-columns:140px 1fr 40px;align-items:center;gap:8px;background:none;border:1px solid transparent;border-radius:3px;padding:3px 4px;color:var(--vscode-foreground);font:inherit;font-size:12px;cursor:pointer;text-align:left}
.hbr:hover{background:var(--vscode-list-hoverBackground)}
.hbr.on{border-color:var(--vscode-focusBorder);background:#04395e66}
.hbt{height:12px;position:relative}
.hbf{display:block;height:12px;background:var(--c);border-radius:0 4px 4px 0;min-width:3px}
.hbf.hatch{background:repeating-linear-gradient(45deg,var(--c) 0 2px,transparent 2px 5px);outline:1px solid var(--c);outline-offset:-1px}
.rg{padding:10px 12px}.rgh{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:12.5px}.rgt{font-weight:600;font-size:13px}
.cntb{background:#a371f733;color:#e0d4ff;border-radius:9px;padding:0 8px;font-size:11px;line-height:18px}
.rkl{margin:8px 0 0 24px;display:flex;flex-direction:column;gap:7px}
.rk{display:flex;gap:9px;font-size:12.5px;line-height:18px}.rkic{color:#cf7a14;flex:none;width:14px}.rk.res .rkic{color:var(--vscode-charts-green)}.rk.res{color:var(--vscode-disabledForeground)}
.rks{font-size:11.5px;color:var(--vscode-descriptionForeground)}
.hbv{text-align:right;font-variant-numeric:tabular-nums;color:#fff}

